"closing_stock": "0", "closing_backlog": "2", "closing_on_order": "0"}, {"date": "2026-01-03", "review": false, "order_due": null, "demand": "4", "lost_sales": "1.125", "opening_stock": "0", "receipts": "0", "backlog_fulfilled": "0", "order_quantity": "0", "immediate_fulfilled": "0", "new_backlog": "4", "closing_stock": "0", "closing_backlog": "6", "closing_on_order": "0"}, {"date": "2026-01-04", "review": true, "order_due": "2026-01-05", "demand": "4", "lost_sales": "1.125", "opening_stock": "0", "receipts": "0", "backlog_fulfilled": "0", "order_quantity": "6", "immediate_fulfilled": "0", "new_backlog": "4", "closing_stock": "0", "closing_backlog": "10", "closing_on_order": "6"}, {"date": "2026-01-05", "review": false, "order_due": null, "demand": "4", "lost_sales": "1.125", "opening_stock": "0", "receipts": "6", "backlog_fulfilled": "6", "order_quantity": "0", "immediate_fulfilled": "0", "new_backlog": "4", "closing_stock": "0", "closing_backlog": "8", "closing_on_order": "0"}], "metrics": {"days": 4, "order_count": 1, "backlog_days": 4, "sold_quantity": "16", "lost_sales_quantity": "4.5", "ordered_quantity": "6", "received_quantity": "6", "immediate_fulfilled": "2", "closing_stock_sum": "0", "average_closing_stock": "0", "immediate_fill_rate": "0.125", "ending_stock": "0", "ending_backlog": "8", "ending_on_order": "0"}}, {"name": "alternative-2", "maximum": "6", "ledger": [{"date": "2026-01-02", "review": true, "order_due": "2026-01-03", "demand": "4", "lost_sales": "1.125", "opening_stock": "2", "receipts": "0", "backlog_fulfilled": "0", "order_quantity": "4", "immediate_fulfilled": "2", "new_backlog": "2", "closing_stock": "0", "closing_backlog": "2", "closing_on_order": "4"}, {"date": "2026-01-03", "review": false, "order_due": null, "demand": "4", "lost_sales": "1.125", "opening_stock": "0", "receipts": "4", "backlog_fulfilled": "2", "order_quantity": "0", "immediate_fulfilled": "2", "new_backlog": "2", "closing_stock": "0", "closing_backlog": "2", "closing_o